select ok(not has_table_privilege('anon', 'public.assignments', 'SELECT'), 'anonymous users cannot read assignments');
select ok(has_table_privilege('authenticated', 'public.assignments', 'INSERT'), 'authenticated assignment insert is enabled for RLS-authorized faculty');
select ok(has_table_privilege('authenticated', 'public.assignments', 'SELECT'), 'authenticated assignment creation can return rows visible through RLS');
select ok(exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'assignments' and policyname = 'members read class assignments' and cmd = 'SELECT' and qual ilike '%private.can_access_assignment%'), 'assignment row visibility remains restricted by RLS');
select ok(has_table_privilege('authenticated', 'public.class_faculty', 'SELECT'), 'authenticated faculty can read assignment permission rows through RLS');
select ok(exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'class_faculty' and policyname = 'class faculty see assignments' and cmd = 'SELECT' and qual ilike '%faculty_id%'), 'class faculty permission rows remain restricted by RLS');
select ok(not has_table_privilege('authenticated', 'public.assignment_submissions', 'INSERT'), 'submissions can only be inserted by the trusted server route');
select ok(not has_table_privilege('authenticated', 'public.enrollment_codes', 'SELECT'), 'enrollment code hashes are not exposed through the Data API');
select ok(has_function_privilege('authenticated', 'private.is_faculty_in_class(uuid,uuid)', 'EXECUTE'), 'college-scoped faculty helper is executable by authenticated RLS policies');
select ok(has_function_privilege('authenticated', 'private.can_manage_class(uuid)', 'EXECUTE'), 'class assignment permission helper is executable by authenticated RLS policies');
select ok(not has_function_privilege('anon', 'private.can_manage_class(uuid)', 'EXECUTE'), 'anonymous users cannot execute the assignment permission helper');
select ok((select prosrc ilike '%c.college_id = private.current_college_id()%' from pg_proc where oid = 'private.can_manage_class(uuid)'::regprocedure), 'class assignment permission is scoped to the current college');
select ok((select with_check ilike '%created_by = (select auth.uid())%' and with_check ilike '%private.can_manage_class%' from pg_policies where schemaname = 'public' and tablename = 'assignments' and policyname = 'faculty create assignments in assigned classes'), 'assignment publishing requires the authenticated creator and class permission');
select ok(has_function_privilege('authenticated', 'public.get_my_quiz_attempts(uuid)', 'EXECUTE'), 'students can retrieve safe quiz attempt summaries');
select ok((select prosrc ilike '%jsonb_each%' from pg_proc where oid = 'public.submit_quiz_attempt(uuid,jsonb)'::regprocedure), 'quiz submission validates answer keys against quiz questions');
select ok((select prosrc ilike '%v_total_score%' and prosrc ilike '%last_activity_date%' from pg_proc where oid = 'public.submit_quiz_attempt(uuid,jsonb)'::regprocedure), 'quiz submission retains grading and updates daily learning streaks');
select ok((select prosrc ilike '%scheduled_at <= now()%' from pg_proc where oid = 'private.can_view_stream_post(uuid)'::regprocedure), 'scheduled stream posts stay hidden until publication time');
select ok(has_function_privilege('authenticated', 'private.can_view_stream_post(uuid)', 'EXECUTE'), 'stream visibility helper is executable by authenticated RLS policies');
select ok(has_function_privilege('authenticated', 'public.submit_quiz_attempt(uuid,jsonb)', 'EXECUTE'), 'students can submit attempts only through the restricted server-side function');
select ok(not has_table_privilege('authenticated', 'public.student_learning_stats', 'INSERT'), 'students cannot insert learning statistics');
select ok(not has_table_privilege('authenticated', 'public.student_learning_stats', 'UPDATE'), 'students cannot update learning statistics');
select ok(not has_table_privilege('authenticated', 'public.student_learning_stats', 'DELETE'), 'students cannot delete learning statistics');
select ok(not has_table_privilege('authenticated', 'public.quiz_attempts', 'INSERT'), 'clients cannot insert quiz attempts outside the restricted function');
