select ok(not has_table_privilege('authenticated', 'public.quiz_attempts', 'DELETE'), 'clients cannot delete quiz attempts');
select ok(not has_column_privilege('authenticated', 'public.quiz_attempts', 'score', 'INSERT'), 'students cannot set quiz scores during attempt insertion');
select ok(not has_column_privilege('authenticated', 'public.quiz_attempts', 'score', 'UPDATE'), 'students cannot update quiz scores');
